int runSliceEnd451(){juce::ScopedJuceInitialiser_GUI gui;LibraryPreparation::checksPaused=true;std::cout.setf(std::ios::unitbuf);try{auto require=[](bool ok,const char* message){if(!ok)throw std::runtime_error(message);};auto data=std::make_shared<AudioData>();data->rate=48000;data->path=LibraryStore::root().getChildFile("uneven-stabs.wav").getFullPathName();data->buffer.setSize(1,96000);for(int n=0;n<96000;++n)data->buffer.setSample(0,n,.2f);Processor p(false);p.autoSave=false;p.audio=data;p.sourceBpm=120;p.sourceBeats=4;p.sourceBeatsPerBar=4;p.normaliseEnabled=false;p.swingLinked=false;p.quantizeEnabled=false;p.swingEnabled=false;p.setPlayMode(false);p.slices={{0,12000,36},{12000,48000,37},{48000,93600,38},{93600,96000,39}};p.prepareToPlay(48000,512);p.resetHistory();
 Editor editor(p,false);editor.setSize(1100,1000);editor.setVisible(true);editor.selectAll.onClick();editor.resized();auto parentClick=[&](juce::Component& target){auto point=target.getLocalBounds().getCentre().toFloat();auto event=juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),point,juce::ModifierKeys::leftButtonModifier,1,0,0,0,0,&target,&target,juce::Time::getCurrentTime(),point,juce::Time::getCurrentTime(),1,false);editor.mouseDown(event);};for(auto* target:std::vector<juce::Component*>{&editor.sliceEnd,&editor.sliceEndFade,&editor.sliceEndReset,&editor.sliceEndLabel,&editor.sliceEndFadeLabel}){parentClick(*target);require(editor.wave.selected.size()==4&&editor.sliceEnd.isEnabled()&&editor.attack.isEnabled(),"parent click on end/fade/reset preserves Select All and enabled envelope controls");}for(auto* child:editor.sliceEnd.getChildren()){parentClick(*child);require(editor.wave.selected.size()==4&&editor.sliceEnd.isEnabled(),"End text-box child click preserves selection");}require(editor.sliceEnd.isEnabled()&&editor.sliceEnd.isVisible(),"End knob enabled for selected slices");auto point=editor.sliceEnd.getBounds().getCentre();auto* hit=editor.getComponentAt(point);require(hit!=nullptr,"knob hit test returns a component");std::cout<<"End knob hit: "<<hit->getName()<<" / "<<typeid(*hit).name()<<" bounds "<<hit->getBounds().toString()<<"\n";require(hit==&editor.sliceEnd||editor.sliceEnd.isParentOf(hit),"End knob receives mouse clicks");
 editor.sliceEnd.onDragStart();editor.sliceEnd.setValue(80,juce::sendNotificationSync);editor.refresh();editor.sliceEnd.onDragEnd();for(auto& s:p.slices)require(s.playbackLengthMs==80&&s.audibleEnd(data->rate)==juce::jmin(s.end,s.start+3840),"bulk 80ms trims each uneven slice from its own start");require(p.undoRedo(false)&&p.slices[0].playbackLengthMs<0&&p.slices[1].playbackLengthMs<0,"bulk duration gesture undo");require(p.undoRedo(true)&&p.slices[0].playbackLengthMs==80,"duration redo");
 // Drive the actual knob mouse handlers, with a refresh between drag frames.
 editor.refresh();auto event=[&](float x,float y,float downY){return juce::MouseEvent(juce::Desktop::getInstance().getMainMouseSource(),{x,y},juce::ModifierKeys::leftButtonModifier,1,0,0,0,0,&editor.sliceEnd,&editor.sliceEnd,juce::Time::getCurrentTime(),{x,downY},juce::Time::getCurrentTime(),1,true);};float x=editor.sliceEnd.getWidth()/2.f,y=editor.sliceEnd.getHeight()-18;editor.mouseDown(event(x,y,y));require(editor.wave.selected.size()==4,"real parent mouse-down retains selection before knob drag");editor.sliceEnd.mouseDown(event(x,y,y));editor.sliceEnd.mouseDrag(event(x,y-15,y));editor.refresh();editor.sliceEnd.mouseDrag(event(x,y-30,y));editor.sliceEnd.mouseUp(event(x,y-30,y));require(p.slices[0].playbackLengthMs>80,"actual knob drag changes duration despite UI refresh");editor.sliceEnd.setValue(80,juce::sendNotificationSync);p.setSliceEnd({0,1,2,3},1,5,false,true);
 auto xml=p.configurationXml(true);Processor recalled(false);recalled.audio=data;require(recalled.applyConfiguration(*xml,true)&&recalled.slices[2].playbackLengthMs==80&&recalled.slices[3].audibleEnd(48000)==96000,"absolute duration recall and short-slice cap");auto legacy=p.configurationXml(true);for(auto* child:legacy->getChildIterator())if(child->hasTagName("slice")){child->removeAttribute("playbackLengthMs");child->setAttribute("playbackEnd",.5);}require(recalled.applyConfiguration(*legacy,true)&&recalled.slices[1].audibleEnd(48000)==30000,"0.45 percentage trims preserved");
 auto output=renderLoopAudio(AudioExportSnapshot::capture(p));require(output.getNumSamples()==96000,"loop export length unchanged");require(output.getMagnitude(0,5000,6000)<1e-6f&&output.getMagnitude(0,17000,30000)<1e-6f,"export cuts each stab tail independently");require(output.getMagnitude(0,13000,1000)>.15f,"second stab remains at original onset");p.clearVoices();p.startVoice(p.slices[1],1);require(p.voices[0].end==15840&&p.voices[0].endFadeSamples==240,"playback uses absolute ms and fade");editor.sliceEndReset.onClick();for(auto& s:p.slices)require(s.playbackLengthMs<0&&s.audibleEnd(48000)==s.end&&s.endFadeMs==0,"reset restores variable full slice lengths");
 auto image=editor.createComponentSnapshot(editor.getLocalBounds());juce::FileOutputStream file(LibraryStore::root().getChildFile("end-ms-editor.png"));juce::PNGImageFormat().writeImageToStream(image,file);std::cout<<"End ms: Select All plus parent/child mouse dispatch, knob hit/drag and numeric entry, uneven 80ms bulk stabs, 50ms boundary cap, playback/export, Undo/Redo, legacy recall and Reset passed\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 4511;}}
